import { test, expect } from '@playwright/test';

test.describe('2. Бизнес-профиль — встроенная карта', () => {
  test('2.1 Гость видит адрес без карты @desktop @prod-safe (#6a7c8dc36076099644cfa2b8)', async ({ page }) => {
    const staticMapRequests: string[] = [];
    page.on('request', (req) => {
      if (req.url().includes('static-map')) staticMapRequests.push(req.url());
    });

    // 1. Открыть `/u/MM9548` (SSR может вернуть 404 — не относится; ждать заголовка профиля).
    await page.goto('/u/MM9548');
    await expect(page.getByRole('heading', { level: 1 }).first()).toBeVisible();

    // 2. Найти секцию Location (he: «מיקום»).
    const locationHeading = page.getByRole('heading', { name: /Location|מיקום/ });
    await expect(locationHeading).toBeVisible();

    // Метка «Business profile» и ссылка-адрес
    await expect(page.getByText(/Business profile|פרופיל עסקי/)).toBeVisible();
    await expect(page.getByRole('link', { name: /bat yam/i })).toBeVisible();

    // Изображения карты нет, запроса static-map нет
    await expect(page.locator('img[src^="data:image/png"]')).toHaveCount(0);
    expect(staticMapRequests).toHaveLength(0);
  });
});
